package com.glisco.numismaticoverhaul;

import com.glisco.numismaticoverhaul.currency.CurrencyComponent;
import dev.onyxstudios.cca.api.v3.component.ComponentKey;
import dev.onyxstudios.cca.api.v3.component.ComponentRegistry;
import dev.onyxstudios.cca.api.v3.entity.EntityComponentFactoryRegistry;
import dev.onyxstudios.cca.api.v3.entity.EntityComponentInitializer;
import dev.onyxstudios.cca.api.v3.entity.RespawnCopyStrategy;
import net.minecraft.util.Identifier;

public class ModComponents implements EntityComponentInitializer {

    public static final ComponentKey<CurrencyComponent> CURRENCY = ComponentRegistry.getOrCreate(new Identifier("numismatic-overhaul", "currency"), CurrencyComponent.class);

    @Override
    public void registerEntityComponentFactories(EntityComponentFactoryRegistry registry) {
        registry.registerForPlayers(CURRENCY, CurrencyComponent::new, RespawnCopyStrategy.ALWAYS_COPY);
    }
}

package com.glisco.numismaticoverhaul;

import com.glisco.numismaticoverhaul.block.*;
import com.glisco.numismaticoverhaul.block.pawn.PawnShopScreenHandler;
import com.glisco.numismaticoverhaul.block.piggy.PiggyBankScreenHandler;
import com.glisco.numismaticoverhaul.block.shop.ShopScreenHandler;
import com.glisco.numismaticoverhaul.currency.MoneyBagLootEntry;
import com.glisco.numismaticoverhaul.item.MoneyBagItem;
import com.glisco.numismaticoverhaul.item.NumismaticOverhaulItems;
import com.glisco.numismaticoverhaul.network.*;
import com.glisco.numismaticoverhaul.recipe.PiggyBankColoringRecipe;
import com.glisco.numismaticoverhaul.villagers.data.VillagerTradesResourceListener;
import com.glisco.numismaticoverhaul.villagers.json.VillagerTradesHandler;
import io.wispforest.owo.itemgroup.Icon;
import io.wispforest.owo.itemgroup.OwoItemGroup;
import io.wispforest.owo.itemgroup.gui.ItemGroupButton;
import io.wispforest.owo.network.OwoNetChannel;
import io.wispforest.owo.ops.LootOps;
import io.wispforest.owo.particles.ClientParticles;
import io.wispforest.owo.particles.systems.ParticleSystem;
import io.wispforest.owo.particles.systems.ParticleSystemController;
import io.wispforest.owo.registration.reflect.FieldRegistrationHandler;
import net.fabricmc.api.ModInitializer;
import net.fabricmc.fabric.api.command.v2.CommandRegistrationCallback;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents;
import net.fabricmc.fabric.api.gamerule.v1.GameRuleFactory;
import net.fabricmc.fabric.api.gamerule.v1.GameRuleRegistry;
import net.fabricmc.fabric.api.loot.v2.LootTableEvents;
import net.fabricmc.fabric.api.resource.ResourceManagerHelper;
import net.minecraft.block.Block;
import net.minecraft.entity.EntityType;
import net.minecraft.entity.SpawnGroup;
import net.minecraft.loot.LootPool;
import net.minecraft.loot.LootTables;
import net.minecraft.loot.condition.RandomChanceLootCondition;
import net.minecraft.loot.entry.LootPoolEntryType;
import net.minecraft.particle.BlockStateParticleEffect;
import net.minecraft.particle.ParticleTypes;
import net.minecraft.recipe.RecipeSerializer;
import net.minecraft.recipe.SpecialRecipeSerializer;
import net.minecraft.registry.*;
import net.minecraft.registry.tag.TagKey;
import net.minecraft.resource.ResourceType;
import net.minecraft.resource.featuretoggle.FeatureFlags;
import net.minecraft.screen.ScreenHandlerType;
import net.minecraft.server.MinecraftServer;
import net.minecraft.sound.SoundEvent;
import net.minecraft.util.Identifier;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.GameRules;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

public class NumismaticOverhaul implements ModInitializer {

    public static final String MOD_ID = "numismatic-overhaul";
    public static final Logger LOGGER = LogManager.getLogger(MOD_ID);

    public static final OwoNetChannel CHANNEL = OwoNetChannel.create(id("main"));
    public static final TagKey<Block> PIGGY_BANKS = TagKey.of(RegistryKeys.BLOCK, id("piggy_banks"));
    private static final ParticleSystemController PARTICLE_SYSTEMS = new ParticleSystemController(id("particles"));
    public static final ParticleSystem<Integer> PIGGY_BANK_BROKEN = PARTICLE_SYSTEMS.register(Integer.class, (world, pos, data) -> {
        ClientParticles.setParticleCount(6 * data);
        ClientParticles.randomizeVelocity(2);
        ClientParticles.spawnCenteredOnBlock(
            new BlockStateParticleEffect(ParticleTypes.BLOCK, NumismaticOverhaulBlocks.PIGGY_BANK.getDefaultState()),
            world, new BlockPos((int) pos.x, (int) pos.y, (int) pos.z), .75
        );
    });

    public static final RecipeSerializer<PiggyBankColoringRecipe> PIGGY_BANK_COLORING_RECIPE = RecipeSerializer.register(MOD_ID + ":piggy_bank_coloring", new SpecialRecipeSerializer<>(PiggyBankColoringRecipe::new));
    public static final ScreenHandlerType<ShopScreenHandler> SHOP_SCREEN_HANDLER_TYPE = new ScreenHandlerType<>(ShopScreenHandler::new, FeatureFlags.DEFAULT_ENABLED_FEATURES);
    public static final ScreenHandlerType<PawnShopScreenHandler> PAWN_SHOP_SCREEN_HANDLER_TYPE = new ScreenHandlerType<>(PawnShopScreenHandler::new, FeatureFlags.DEFAULT_ENABLED_FEATURES);
    public static final ScreenHandlerType<PiggyBankScreenHandler> PIGGY_BANK_SCREEN_HANDLER_TYPE = new ScreenHandlerType<>(PiggyBankScreenHandler::new, FeatureFlags.DEFAULT_ENABLED_FEATURES);

    public static final SoundEvent PIGGY_BANK_BREAK = SoundEvent.of(id("piggy_bank_break"));
    public static final LootPoolEntryType MONEY_BAG_ENTRY = new LootPoolEntryType(new MoneyBagLootEntry.Serializer());

    public static final TagKey<EntityType<?>> THE_BOURGEOISIE = TagKey.of(RegistryKeys.ENTITY_TYPE, id("the_bourgeoisie"));
    public static final TagKey<Block> VERY_HEAVY_BLOCKS = TagKey.of(RegistryKeys.BLOCK, id("very_heavy_blocks"));

    public static final GameRules.Key<GameRules.IntRule> MONEY_DROP_PERCENTAGE
        = GameRuleRegistry.register("moneyDropPercentage", GameRules.Category.PLAYER, GameRuleFactory.createIntRule(10, 0, 100));

    public static final GameRules.Key<GameRules.IntRule> MONEY_MOB_DROP_VARIANCE
        = GameRuleRegistry.register("moneyMobDropVariancePercentage", GameRules.Category.MOBS, GameRuleFactory.createIntRule(50, 0, 100));

    public static final OwoItemGroup NUMISMATIC_GROUP = OwoItemGroup.builder(
            NumismaticOverhaul.id("main"),
            () -> Icon.of(MoneyBagItem.createCombined(new long[]{0, 1, 0})))
        .initializer(group -> {
            group.addButton(ItemGroupButton.modrinth(group, "https://modrinth.com/mod/numismatic-overhaul"));
            group.addButton(ItemGroupButton.curseforge(group, "https://www.curseforge.com/minecraft/mc-mods/numismatic-overhaul"));
            group.addButton(ItemGroupButton.github(group, "https://github.com/wisp-forest/numismatic-overhaul"));
            group.addButton(ItemGroupButton.discord(group, "https://discord.gg/xrwHKktV2d"));
        }).build();

    public static final Map<EntityType<?>, Integer> MOBS_IN_BOURGEOISIE = new HashMap<>();

    public static final com.glisco.numismaticoverhaul.NumismaticOverhaulConfig CONFIG = com.glisco.numismaticoverhaul.NumismaticOverhaulConfig.createAndLoad();

    @Override
    public void onInitialize() {
        // this type of code truly feels like DH code
        ServerLifecycleEvents.SERVER_STARTED.register(NumismaticOverhaul::loadMobDropConfig);

        FieldRegistrationHandler.register(NumismaticOverhaulItems.class, MOD_ID, false);
        FieldRegistrationHandler.register(NumismaticOverhaulBlocks.class, MOD_ID, false);
        FieldRegistrationHandler.register(NumismaticOverhaulBlocks.Entities.class, MOD_ID, false);

        Registry.register(Registries.SOUND_EVENT, PIGGY_BANK_BREAK.getId(), PIGGY_BANK_BREAK);
        Registry.register(Registries.LOOT_POOL_ENTRY_TYPE, id("money_bag"), MONEY_BAG_ENTRY);

        Registry.register(Registries.SCREEN_HANDLER, id("shop"), SHOP_SCREEN_HANDLER_TYPE);
        Registry.register(Registries.SCREEN_HANDLER, id("piggy_bank"), PIGGY_BANK_SCREEN_HANDLER_TYPE);

        CHANNEL.registerServerbound(RequestPurseActionC2SPacket.class, RequestPurseActionC2SPacket::handle);
        CHANNEL.registerServerbound(ShopScreenHandlerRequestC2SPacket.class, ShopScreenHandlerRequestC2SPacket::handle);
        CHANNEL.registerServerbound(PawnShopScreenHandlerRequestC2SPacket.class, PawnShopScreenHandlerRequestC2SPacket::handle);
        UpdateShopScreenS2CPacket.initialize();
        UpdatePawnShopScreenS2CPacket.initialize();

        ResourceManagerHelper.get(ResourceType.SERVER_DATA).registerReloadListener(new VillagerTradesResourceListener());
        VillagerTradesHandler.registerDefaultAdapters();

        CommandRegistrationCallback.EVENT.register(NumismaticCommand::register);

        ServerLifecycleEvents.END_DATA_PACK_RELOAD.register((server, serverResourceManager, success) -> {
            VillagerTradesHandler.broadcastErrors(server);
            NumismaticOverhaul.reloadMobDropConfig();
        });

        NUMISMATIC_GROUP.initialize();

        if (CONFIG.generateCurrencyInChests()) {
            LootOps.injectItem(NumismaticOverhaulItems.GOLD_COIN, .01f, LootTables.STRONGHOLD_LIBRARY_CHEST, LootTables.BASTION_TREASURE_CHEST, LootTables.STRONGHOLD_CORRIDOR_CHEST,
                LootTables.PILLAGER_OUTPOST_CHEST, LootTables.BURIED_TREASURE_CHEST, LootTables.SIMPLE_DUNGEON_CHEST, LootTables.ABANDONED_MINESHAFT_CHEST);

            LootTableEvents.MODIFY.register((resourceManager, lootManager, id, tableBuilder, source) -> {
                if (anyMatch(id, LootTables.DESERT_PYRAMID_CHEST)) {
                    tableBuilder.pool(LootPool.builder().with(MoneyBagLootEntry.builder(CONFIG.lootOptions.desertMinLoot(), CONFIG.lootOptions.desertMaxLoot()))
                        .conditionally(RandomChanceLootCondition.builder(0.45f)));
                } else if (anyMatch(id, LootTables.SIMPLE_DUNGEON_CHEST, LootTables.ABANDONED_MINESHAFT_CHEST)) {
                    tableBuilder.pool(LootPool.builder().with(MoneyBagLootEntry.builder(CONFIG.lootOptions.dungeonMinLoot(), CONFIG.lootOptions.dungeonMaxLoot()))
                        .conditionally(RandomChanceLootCondition.builder(0.75f)));
                } else if (anyMatch(id, LootTables.BASTION_TREASURE_CHEST, LootTables.STRONGHOLD_CORRIDOR_CHEST, LootTables.PILLAGER_OUTPOST_CHEST, LootTables.BURIED_TREASURE_CHEST)) {
                    tableBuilder.pool(LootPool.builder().with(MoneyBagLootEntry.builder(CONFIG.lootOptions.structureMinLoot(), CONFIG.lootOptions.structureMaxLoot()))
                        .conditionally(RandomChanceLootCondition.builder(0.75f)));
                } else if (anyMatch(id, LootTables.STRONGHOLD_LIBRARY_CHEST)) {
                    tableBuilder.pool(LootPool.builder().with(MoneyBagLootEntry.builder(CONFIG.lootOptions.strongholdLibraryMinLoot(), CONFIG.lootOptions.strongholdLibraryMaxLoot()))
                        .conditionally(RandomChanceLootCondition.builder(0.85f)));
                }
            });
        }
    }

    private static boolean anyMatch(Identifier target, Identifier... comparisons) {
        for (Identifier comparison : comparisons) {
            if (target.equals(comparison)) return true;
        }
        return false;
    }

    public static Identifier id(String path) {
        return new Identifier(MOD_ID, path);
    }

    private static void loadMobDropConfig(MinecraftServer ignored) {
        CONFIG.mobsToBaseValues().forEach((s, baseValue) -> {
            if (s.startsWith("€")) {
                var potentialGroup = s.split("€")[1];
                try {
                    var group = SpawnGroup.valueOf(potentialGroup.toUpperCase(Locale.ROOT));
                    Registries.ENTITY_TYPE.forEach(entityType -> {
                        if (entityType.getSpawnGroup() == group) {
                            MOBS_IN_BOURGEOISIE.put(entityType, baseValue);
                        }
                    });
                } catch (IllegalArgumentException e) {
                    LOGGER.error("[Numismatic Overhaul] Could not find spawn group '{}' for mob drops", s);
                }
            }
            else if (s.startsWith("@")) {
                var namespace = s.split("@")[1];
                Registries.ENTITY_TYPE.getEntrySet().forEach(entry -> {
                    var entityNamespace = entry.getKey().getValue().getNamespace();
                    if (entityNamespace.equals(namespace)) {
                        MOBS_IN_BOURGEOISIE.put(entry.getValue(), baseValue);
                    }
                });
            }
            else if (s.startsWith("#")) {
                Registries.ENTITY_TYPE.getEntryList(TagKey.of(RegistryKeys.ENTITY_TYPE, Identifier.tryParse(s.split("#")[1]))).ifPresent(registryEntries -> {
                    registryEntries.forEach(entityTypeRegistryEntry -> MOBS_IN_BOURGEOISIE.put(entityTypeRegistryEntry.value(), baseValue));
                });
            } else {
                var entityOpt = Registries.ENTITY_TYPE.getOrEmpty(Identifier.tryParse(s));
                entityOpt.ifPresentOrElse(entityType -> MOBS_IN_BOURGEOISIE.put(entityType, baseValue), () -> {
                    LOGGER.error("[Numismatic Overhaul] Could not find entity type or entity type tag '{}' for mob drops", s);
                });
            }
        });
    }

    private static void reloadMobDropConfig() {
        MOBS_IN_BOURGEOISIE.clear();
        CONFIG.load();
        loadMobDropConfig(null);
    }
}

package com.glisco.numismaticoverhaul.block.pawn;

import com.glisco.numismaticoverhaul.NumismaticOverhaul;
import com.glisco.numismaticoverhaul.block.NumismaticOverhaulBlocks;
import com.glisco.numismaticoverhaul.currency.CurrencyConverter;
import com.glisco.numismaticoverhaul.network.UpdatePawnShopScreenS2CPacket;
import net.fabricmc.fabric.api.object.builder.v1.block.FabricBlockSettings;
import net.minecraft.block.*;
import net.minecraft.block.entity.BlockEntity;
import net.minecraft.block.entity.BlockEntityTicker;
import net.minecraft.block.entity.BlockEntityType;
import net.minecraft.entity.LivingEntity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.item.ItemStack;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.text.Text;
import net.minecraft.util.ActionResult;
import net.minecraft.util.Hand;
import net.minecraft.util.ItemScatterer;
import net.minecraft.util.hit.BlockHitResult;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.shape.VoxelShape;
import net.minecraft.util.shape.VoxelShapes;
import net.minecraft.world.BlockView;
import net.minecraft.world.World;
import org.jetbrains.annotations.Nullable;

public class PawnShopBlock extends BlockWithEntity {

    private static final VoxelShape MAIN_PILLAR = Block.createCuboidShape(1, 0, 1, 14, 8, 14);

    private static final VoxelShape PLATE = Block.createCuboidShape(0, 8, 0, 16, 12, 16);

    private static final VoxelShape PILLAR_1 = Block.createCuboidShape(13, 0, 0, 16, 8, 3);
    private static final VoxelShape PILLAR_2 = Block.createCuboidShape(0, 0, 0, 3, 8, 3);
    private static final VoxelShape PILLAR_3 = Block.createCuboidShape(0, 0, 13, 3, 8, 16);
    private static final VoxelShape PILLAR_4 = Block.createCuboidShape(13, 0, 13, 16, 8, 16);

    private static final VoxelShape SHAPE = VoxelShapes.union(MAIN_PILLAR, PLATE, PILLAR_1, PILLAR_2, PILLAR_3, PILLAR_4);

    private final boolean inexhaustible;

    public PawnShopBlock(boolean inexhaustible) {
        super(FabricBlockSettings.create().nonOpaque().hardness(5.0f));
        this.inexhaustible = inexhaustible;
    }

    @Override
    public BlockRenderType getRenderType(BlockState state) {
        return BlockRenderType.MODEL;
    }

    @Override
    public VoxelShape getOutlineShape(BlockState state, BlockView world, BlockPos pos, ShapeContext context) {
        return SHAPE;
    }

    @Override
    public ActionResult onUse(BlockState state, World world, BlockPos pos, PlayerEntity player, Hand hand, BlockHitResult hit) {
        if (!world.isClient) {
            PawnShopBlockEntity blockEntity = (PawnShopBlockEntity) world.getBlockEntity(pos);
            if (blockEntity == null) return ActionResult.FAIL;
            if (blockEntity.busy) return ActionResult.SUCCESS;

            if (blockEntity.getOwner().equals(player.getUuid()) && !player.isSneaking()) {
                player.openHandledScreen(state.createScreenHandlerFactory(world, pos));
                NumismaticOverhaul.CHANNEL.serverHandle(player).send(new UpdatePawnShopScreenS2CPacket(blockEntity));

                blockEntity.busy = true;
            } else {
                ((PawnShopMerchant) blockEntity.getMerchant()).updateTrades();
                blockEntity.getMerchant().setCustomer(player);
                blockEntity.getMerchant().sendOffers(player, Text.translatable("gui.numismatic-overhaul.pawn_shop.merchant_title"), 0);

                return ActionResult.SUCCESS;
            }
        }

        return ActionResult.SUCCESS;
    }

    @Override
    public void onPlaced(World world, BlockPos pos, BlockState state, @Nullable LivingEntity placer, ItemStack itemStack) {
        if (world.isClient) return;

        if (!(placer instanceof ServerPlayerEntity)) {
            world.breakBlock(pos, true);
            return;
        }

        if (itemStack.hasCustomName() && world.getBlockEntity(pos) instanceof PawnShopBlockEntity shop) {
            shop.setCustomName(itemStack.getName());
        }

        ((PawnShopBlockEntity) world.getBlockEntity(pos)).setOwner(placer.getUuid());
    }

    @Override
    public void onStateReplaced(BlockState state, World world, BlockPos pos, BlockState newState, boolean moved) {
        if (state.getBlock() != newState.getBlock()) {
            if (world.getBlockEntity(pos) instanceof PawnShopBlockEntity shop) {
                shop.getMerchant().setCustomer(null);

                CurrencyConverter.getAsValidStacks(shop.getStoredCurrency())
                        .forEach(stack -> ItemScatterer.spawn(shop.getWorld(), pos.getX(), pos.getY(), pos.getZ(), stack));

                ItemScatterer.spawn(world, pos, shop);
            }
            super.onStateReplaced(state, world, pos, newState, moved);
        }
    }

    public boolean inexhaustible() {
        return this.inexhaustible;
    }

    @Nullable
    @Override
    public BlockEntity createBlockEntity(BlockPos pos, BlockState state) {
        return new PawnShopBlockEntity(pos, state);
    }

    @Nullable
    @Override
    public <T extends BlockEntity> BlockEntityTicker<T> getTicker(World world, BlockState state, BlockEntityType<T> type) {
        return checkType(type, NumismaticOverhaulBlocks.Entities.PAWN_SHOP, PawnShopBlockEntity::tick);
    }
}

package com.glisco.numismaticoverhaul.block.pawn;

import com.glisco.numismaticoverhaul.NumismaticOverhaul;
import com.glisco.numismaticoverhaul.block.NumismaticOverhaulBlocks;
import io.wispforest.owo.ops.WorldOps;
import io.wispforest.owo.util.ImplementedInventory;
import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.minecraft.block.BlockState;
import net.minecraft.block.entity.LockableContainerBlockEntity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.entity.player.PlayerInventory;
import net.minecraft.inventory.Inventories;
import net.minecraft.inventory.SidedInventory;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.network.listener.ClientPlayPacketListener;
import net.minecraft.network.packet.Packet;
import net.minecraft.network.packet.s2c.play.BlockEntityUpdateS2CPacket;
import net.minecraft.screen.NamedScreenHandlerFactory;
import net.minecraft.screen.ScreenHandler;
import net.minecraft.text.Text;
import net.minecraft.util.collection.DefaultedList;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.Direction;
import net.minecraft.village.Merchant;
import net.minecraft.world.World;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.stream.IntStream;

public class PawnShopBlockEntity extends LockableContainerBlockEntity implements ImplementedInventory, SidedInventory, NamedScreenHandlerFactory {

    private static final int[] SLOTS = IntStream.range(0, 27).toArray();
    private static final int[] NO_SLOTS = new int[0];

    private final DefaultedList<ItemStack> INVENTORY = DefaultedList.ofSize(27, ItemStack.EMPTY);

    public boolean busy = false;
    private final Merchant merchant;
    private final List<PawnShopOffer> offers;

    private long storedCurrency;
    private UUID owner;
    private boolean allowsTransfer = false;

    private int tradeIndex;

    public PawnShopBlockEntity(BlockPos pos, BlockState state) {
        super(NumismaticOverhaulBlocks.Entities.PAWN_SHOP, pos, state);

        boolean inexhaustible = (state.getBlock() instanceof PawnShopBlock shop) && shop.inexhaustible();
        this.merchant = new PawnShopMerchant(this, inexhaustible);

        this.offers = new ArrayList<>();
        this.storedCurrency = 0;
    }

    @Override
    public DefaultedList<ItemStack> getItems() {
        return INVENTORY;
    }

    @Override
    public int[] getAvailableSlots(Direction side) {
        return allowsTransfer ? SLOTS : NO_SLOTS;
    }

    @Override
    public boolean canInsert(int slot, ItemStack stack, @Nullable Direction dir) {
        return false;
    }

    @Override
    public boolean canExtract(int slot, ItemStack stack, Direction dir) {
        return allowsTransfer;
    }

    @Override
    protected Text getContainerName() {
        return Text.translatable("gui.numismatic-overhaul.pawn_shop.inventory_title");
    }

    @NotNull
    public Merchant getMerchant() {
        return merchant;
    }

    public List<PawnShopOffer> getOffers() {
        return offers;
    }

    public long getStoredCurrency() {
        return storedCurrency;
    }

    public boolean isTransferEnabled() {
        return allowsTransfer;
    }

    public void toggleTransfer() {
        this.allowsTransfer = !this.allowsTransfer;
    }

    public void setStoredCurrency(long storedCurrency) {
        this.storedCurrency = storedCurrency;
        markDirty();
    }

    public void addCurrency(long value) {
        this.storedCurrency += value;
        markDirty();
    }

    public void removeCurrency(int value) {
        this.storedCurrency -= value;
        markDirty();
    }

    @Override
    public void writeNbt(NbtCompound tag) {
        super.writeNbt(tag);
        Inventories.writeNbt(tag, INVENTORY);
        PawnShopOffer.writeAll(tag, offers);
        tag.putBoolean("AllowsTransfer", this.allowsTransfer);
        tag.putLong("StoredCurrency", storedCurrency);
        if (owner != null) {
            tag.putUuid("Owner", owner);
        }
    }

    @Override
    public void readNbt(NbtCompound tag) {
        super.readNbt(tag);
        Inventories.readNbt(tag, INVENTORY);
        PawnShopOffer.readAll(tag, offers);
        if (tag.contains("Owner")) {
            owner = tag.getUuid("Owner");
        }
        this.allowsTransfer = tag.getBoolean("AllowsTransfer");
        this.storedCurrency = tag.getLong("StoredCurrency");
    }

    public void addOrReplaceOffer(PawnShopOffer offer) {
        int indexToReplace = -1;

        for (int i = 0; i < offers.size(); i++) {
            if (!ItemStack.areEqual(offer.getBuyStack(), offers.get(i).getBuyStack())) continue;
            indexToReplace = i;
            break;
        }

        if (indexToReplace == -1) {
            if (offers.size() >= 24) {
                NumismaticOverhaul.LOGGER.error("Tried adding more than 24 trades to shop at {}", this.pos);
                return;
            }
            offers.add(offer);
        } else {
            offers.set(indexToReplace, offer);
        }

        this.markDirty();
    }

    public void deleteOffer(ItemStack stack) {
        if (!offers.removeIf(offer -> ItemStack.areEqual(stack, offer.getBuyStack()))) {
            NumismaticOverhaul.LOGGER.error("Tried to delete invalid trade for {} from shop at {}", stack, this.pos);
            return;
        }

        this.markDirty();
    }

    public static void tick(World world, BlockPos pos, BlockState state, PawnShopBlockEntity blockEntity) {
        blockEntity.tick();
    }

    public void tick() {
        if (world.getTime() % 60 == 0) tradeIndex++;
    }

    @Environment(EnvType.CLIENT)
    public ItemStack getItemToRender() {
        if (tradeIndex > offers.size() - 1) tradeIndex = 0;
        return offers.get(tradeIndex).getBuyStack();
    }

    @Override
    protected ScreenHandler createScreenHandler(int syncId, PlayerInventory playerInventory) {
        return new PawnShopScreenHandler(syncId, playerInventory, this);
    }

    @Override
    public boolean canPlayerUse(PlayerEntity player) {
        return player.getUuid().equals(this.owner) && this.world.getBlockEntity(this.pos) == this && this.pos.getSquaredDistance(player.getX(), player.getY(), player.getZ()) <= 100;
    }

    @Override
    public NbtCompound toInitialChunkDataNbt() {
        NbtCompound tag = new NbtCompound();
        this.writeNbt(tag);
        tag.remove("Items");
        tag.remove("StoredCurrency");
        return tag;
    }

    public UUID getOwner() {
        return owner;
    }

    public void setOwner(UUID owner) {
        this.owner = owner;
        markDirty();
    }

    @Nullable
    @Override
    public Packet<ClientPlayPacketListener> toUpdatePacket() {
        return BlockEntityUpdateS2CPacket.create(this);
    }

    @Override
    public void markDirty() {
        super.markDirty();
        WorldOps.updateIfOnServer(world, pos);
    }
}

package com.glisco.numismaticoverhaul.block.pawn;

import com.glisco.numismaticoverhaul.currency.CurrencyHelper;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.item.ItemStack;
import net.minecraft.network.packet.s2c.play.SetTradeOffersS2CPacket;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.sound.SoundEvent;
import net.minecraft.sound.SoundEvents;
import net.minecraft.util.collection.DefaultedList;
import net.minecraft.village.Merchant;
import net.minecraft.village.TradeOffer;
import net.minecraft.village.TradeOfferList;
import org.jetbrains.annotations.Nullable;

import java.util.List;

public class PawnShopMerchant implements Merchant {

    private final PawnShopBlockEntity shop;
    private final boolean inexhaustible;
    private TradeOfferList recipeList = new TradeOfferList();
    private PlayerEntity customer;

    public PawnShopMerchant(PawnShopBlockEntity blockEntity, boolean inexhaustible) {
        this.shop = blockEntity;
        this.inexhaustible = inexhaustible;
    }

    public void updateTrades() {
        recipeList.clear();
        shop.getOffers().forEach(offer -> recipeList.add(offer.toTradeOffer(shop, this.inexhaustible)));
    }

    @Override
    public void setCustomer(@Nullable PlayerEntity customer) {
        this.customer = customer;
        this.shop.busy = customer != null;
    }

    @Nullable
    @Override
    public PlayerEntity getCustomer() {
        return customer;
    }

    @Override
    public TradeOfferList getOffers() {
        return recipeList;
    }

    @Override
    public void setOffersFromServer(@Nullable TradeOfferList offers) {
        this.recipeList = offers;
    }

    @Override
    public void trade(TradeOffer offer) {
        offer.use();
        if (!this.inexhaustible) {
            PawnShopOffer.add(shop, offer.getOriginalFirstBuyItem());

            shop.removeCurrency(CurrencyHelper.getValue(List.of(offer.getSellItem())));
            this.updateTrades();
            if (this.getCustomer() instanceof ServerPlayerEntity serverPlayer) {
                serverPlayer.networkHandler.sendPacket(new SetTradeOffersS2CPacket(
                        serverPlayer.currentScreenHandler.syncId,
                        this.recipeList,
                        0, 0, false, false
                ));
            }
        }
    }

    @Override
    public void onSellingItem(ItemStack stack) {

    }

    @Override
    public int getExperience() {
        return 0;
    }

    @Override
    public void setExperienceFromServer(int experience) {

    }

    @Override
    public boolean isLeveledMerchant() {
        return false;
    }

    @Override
    public SoundEvent getYesSound() {
        return SoundEvents.ENTITY_VILLAGER_YES;
    }

    @Override
    public boolean isClient() {
        return false;
    }

    public PawnShopBlockEntity shop() {
        return this.shop;
    }
}

package com.glisco.numismaticoverhaul.block.pawn;

import com.glisco.numismaticoverhaul.currency.CurrencyConverter;
import com.glisco.numismaticoverhaul.item.MoneyBagItem;
import com.glisco.numismaticoverhaul.villagers.data.NumismaticTradeOfferExtensions;
import io.wispforest.owo.ops.ItemOps;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.nbt.NbtElement;
import net.minecraft.nbt.NbtList;
import net.minecraft.village.TradeOffer;

import java.util.List;

public class PawnShopOffer {

    private final ItemStack buy;
    private final long price;

    public PawnShopOffer(ItemStack buy, long price) {

        if (buy.isEmpty()) throw new IllegalArgumentException("Buy Stack must not be empty");
        if (price == 0) throw new IllegalArgumentException("Price must not be null");

        this.buy = buy;
        this.price = price;
    }

    public static void add(PawnShopBlockEntity pawnShop, ItemStack boughtStack) {
        var shopItems = pawnShop.getItems();
        // loop once to merge existing stacks together
        for (ItemStack stack : shopItems) {
            if (ItemOps.canStack(stack, boughtStack)) {
                stack.increment(boughtStack.getCount());
                return;
            }
        }
        // then again to fill an empty slot
        for (int i = 0; i < shopItems.size(); i++) {
            if (shopItems.get(i).isEmpty()) {
                pawnShop.setStack(i, boughtStack);
                return;
            }
        }
    }

    @SuppressWarnings("ConstantConditions")
    public TradeOffer toTradeOffer(PawnShopBlockEntity shop, boolean inexhaustible) {
        int maxUses = inexhaustible ? Integer.MAX_VALUE : (int) (shop.getStoredCurrency() / price);
        if (!shop.getItems().contains(ItemStack.EMPTY)) {
            maxUses = 0;
        }
        var money = CurrencyConverter.getRequiredCurrencyTypes(price) == 1 ? CurrencyConverter.getAsItemStackList(price).get(0) : MoneyBagItem.create(price);

        final var tradeOffer = new TradeOffer(getBuyStack(), money, maxUses, 0, 0);
        ((NumismaticTradeOfferExtensions) tradeOffer).numismatic$setReputation(-69420);
        return tradeOffer;
    }

    public long getPrice() {
        return price;
    }

    public ItemStack getBuyStack() {
        return buy.copy();
    }

    public static NbtCompound writeAll(NbtCompound tag, List<PawnShopOffer> offers) {

        NbtList offerList = new NbtList();

        for (PawnShopOffer offer : offers) {
            offerList.add(offer.toNbt());
        }

        tag.put("Offers", offerList);

        return tag;
    }

    public static void readAll(NbtCompound tag, List<PawnShopOffer> offers) {
        offers.clear();

        NbtList offerList = tag.getList("Offers", NbtElement.COMPOUND_TYPE);

        for (NbtElement offerTag : offerList) {
            offers.add(fromNbt((NbtCompound) offerTag));
        }
    }

    public NbtCompound toNbt() {
        var nbt = new NbtCompound();
        nbt.putLong("Price", this.price);

        var itemNbt = new NbtCompound();
        this.buy.writeNbt(itemNbt);

        nbt.put("Item", itemNbt);
        return nbt;
    }

    public static PawnShopOffer fromNbt(NbtCompound nbt) {
        var item = ItemStack.fromNbt(nbt.getCompound("Item"));
        return new PawnShopOffer(item, nbt.getLong("Price"));
    }

    @Override
    public String toString() {
        return this.buy + "@" + this.price + "coins";
    }
}

package com.glisco.numismaticoverhaul.block.pawn;

import com.glisco.numismaticoverhaul.ModComponents;
import com.glisco.numismaticoverhaul.NumismaticOverhaul;
import com.glisco.numismaticoverhaul.client.gui.PawnShopScreen;
import com.glisco.numismaticoverhaul.currency.CurrencyHelper;
import com.glisco.numismaticoverhaul.network.PawnShopScreenHandlerRequestC2SPacket;
import com.glisco.numismaticoverhaul.network.UpdatePawnShopScreenS2CPacket;
import io.wispforest.owo.client.screens.ScreenUtils;
import io.wispforest.owo.client.screens.SlotGenerator;
import io.wispforest.owo.client.screens.SyncedProperty;
import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.minecraft.client.MinecraftClient;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.entity.player.PlayerInventory;
import net.minecraft.inventory.Inventory;
import net.minecraft.inventory.SimpleInventory;
import net.minecraft.item.ItemStack;
import net.minecraft.screen.ScreenHandler;
import net.minecraft.screen.slot.Slot;

import java.util.ArrayList;
import java.util.List;

public class PawnShopScreenHandler extends ScreenHandler {

    private final PlayerEntity owner;

    private final Inventory shopInventory;
    private final SyncedProperty<ItemStack> tradeEditBuffer;

    private final List<PawnShopOffer> offers;

    private PawnShopBlockEntity shop = null;

    public PawnShopScreenHandler(int syncId, PlayerInventory playerInventory) {
        this(syncId, playerInventory, new SimpleInventory(27));
    }

    public PawnShopScreenHandler(int syncId, PlayerInventory playerInventory, Inventory shopInventory) {
        super(NumismaticOverhaul.PAWN_SHOP_SCREEN_HANDLER_TYPE, syncId);
        this.shopInventory = shopInventory;
        this.owner = playerInventory.player;

        if (!this.owner.getWorld().isClient()) {
            this.shop = (PawnShopBlockEntity) shopInventory;
            this.offers = shop.getOffers();
        } else {
            this.offers = new ArrayList<>();
        }

        SlotGenerator.begin(this::addSlot, 8, 17)
                .slotFactory((inv, index, x, y) -> new AutoHidingSlot(inv, index, x, y, 0, false))
                .grid(this.shopInventory, 0, 9, 3)
                .slotFactory(Slot::new)
                .moveTo(8, 85)
                .playerInventory(playerInventory);

        this.tradeEditBuffer = this.createProperty(ItemStack.class, ItemStack.EMPTY);
        this.tradeEditBuffer.observe(stack -> {
            if (this.owner.getWorld().isClient && MinecraftClient.getInstance().currentScreen instanceof PawnShopScreen screen) {
                screen.afterDataUpdate();
            }
        });
    }

    @Override
    public boolean canUse(PlayerEntity player) {
        return this.shopInventory.canPlayerUse(player);
    }

    public void loadOffer(long index) {
        if (!this.owner.getWorld().isClient) {
            if (index > this.offers.size() - 1) {
                NumismaticOverhaul.LOGGER.error("Player {} attempted to load invalid trade at index {}", owner.getName(), index);
                return;
            }

            this.tradeEditBuffer.set(this.offers.get((int) index).getBuyStack());
        } else {
            NumismaticOverhaul.CHANNEL.clientHandle().send(new PawnShopScreenHandlerRequestC2SPacket(PawnShopScreenHandlerRequestC2SPacket.Action.LOAD_OFFER, index));
        }
    }

    public void createOffer(long price) {
        if (!this.owner.getWorld().isClient) {
            final var stack = this.tradeEditBuffer.get();
            if (stack.isEmpty()) return;

            this.shop.addOrReplaceOffer(new PawnShopOffer(stack, price));
            this.updateClient();
        } else {
            NumismaticOverhaul.CHANNEL.clientHandle().send(new PawnShopScreenHandlerRequestC2SPacket(PawnShopScreenHandlerRequestC2SPacket.Action.CREATE_OFFER, price));
        }
    }

    public void insertCurrency() {
        if (!this.owner.getWorld().isClient) {
            var money = CurrencyHelper.getMoneyInInventory(this.owner, true);
            this.shop.addCurrency(money);
            this.updateClient();
        } else {
            NumismaticOverhaul.CHANNEL.clientHandle().send(new PawnShopScreenHandlerRequestC2SPacket(PawnShopScreenHandlerRequestC2SPacket.Action.INSERT_CURRENCY));
        }
    }

    public void extractCurrency() {
        if (!this.owner.getWorld().isClient) {
            ModComponents.CURRENCY.get(owner).modify(shop.getStoredCurrency());
            this.shop.setStoredCurrency(0);
            this.updateClient();
        } else {
            NumismaticOverhaul.CHANNEL.clientHandle().send(new PawnShopScreenHandlerRequestC2SPacket(PawnShopScreenHandlerRequestC2SPacket.Action.EXTRACT_CURRENCY));
        }
    }

    public void deleteOffer() {
        if (!this.owner.getWorld().isClient) {
            this.shop.deleteOffer(this.tradeEditBuffer.get());
            this.updateClient();
        } else {
            NumismaticOverhaul.CHANNEL.clientHandle().send(new PawnShopScreenHandlerRequestC2SPacket(PawnShopScreenHandlerRequestC2SPacket.Action.DELETE_OFFER));
        }
    }

    public void toggleTransfer() {
        if (!this.owner.getWorld().isClient) {
            this.shop.toggleTransfer();
            this.updateClient();
        } else {
            NumismaticOverhaul.CHANNEL.clientHandle().send(new PawnShopScreenHandlerRequestC2SPacket(PawnShopScreenHandlerRequestC2SPacket.Action.TOGGLE_TRANSFER));
        }
    }

    public void handleBufferClick() {
        if (!this.owner.getWorld().isClient) {
            this.tradeEditBuffer.set(this.getCursorStack().copy());
        } else {
            NumismaticOverhaul.CHANNEL.clientHandle().send(new PawnShopScreenHandlerRequestC2SPacket(PawnShopScreenHandlerRequestC2SPacket.Action.CLICK_BUFFER));
        }
    }

    private void updateClient() {
        NumismaticOverhaul.CHANNEL.serverHandle(owner).send(new UpdatePawnShopScreenS2CPacket(shop));
    }

    public ItemStack getBufferStack() {
        return this.tradeEditBuffer.get();
    }

    @Override
    public ItemStack quickMove(PlayerEntity player, int invSlot) {
        return ScreenUtils.handleSlotTransfer(this, invSlot, this.shopInventory.size());
    }

    @Override
    public void onClosed(PlayerEntity player) {
        super.onClosed(player);
        if (this.shop != null) this.shop.busy = false;
    }

    private static class AutoHidingSlot extends Slot {

        private final int targetTab;
        private final boolean hide;

        public AutoHidingSlot(Inventory inventory, int index, int x, int y, int targetTab, boolean hide) {
            super(inventory, index, x, y);
            this.targetTab = targetTab;
            this.hide = hide;
        }

        @Override
        @Environment(EnvType.CLIENT)
        public boolean isEnabled() {
            if (!(MinecraftClient.getInstance().currentScreen instanceof PawnShopScreen screen)) return true;
            //noinspection SimplifiableConditionalExpression
            return hide
                    ? screen.tab() != targetTab
                    : screen.tab() == targetTab;
        }
    }
}

package com.glisco.numismaticoverhaul.block.shop;

import com.glisco.numismaticoverhaul.NumismaticOverhaul;
import com.glisco.numismaticoverhaul.block.NumismaticOverhaulBlocks;
import com.glisco.numismaticoverhaul.currency.CurrencyConverter;
import com.glisco.numismaticoverhaul.network.UpdateShopScreenS2CPacket;
import net.fabricmc.fabric.api.object.builder.v1.block.FabricBlockSettings;
import net.minecraft.block.*;
import net.minecraft.block.entity.BlockEntity;
import net.minecraft.block.entity.BlockEntityTicker;
import net.minecraft.block.entity.BlockEntityType;
import net.minecraft.entity.LivingEntity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.item.ItemStack;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.text.Text;
import net.minecraft.util.ActionResult;
import net.minecraft.util.Hand;
import net.minecraft.util.ItemScatterer;
import net.minecraft.util.hit.BlockHitResult;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.shape.VoxelShape;
import net.minecraft.util.shape.VoxelShapes;
import net.minecraft.world.BlockView;
import net.minecraft.world.World;
import org.jetbrains.annotations.Nullable;

public class ShopBlock extends BlockWithEntity {

    private static final VoxelShape MAIN_PILLAR = Block.createCuboidShape(1, 0, 1, 14, 8, 14);

    private static final VoxelShape PLATE = Block.createCuboidShape(0, 8, 0, 16, 12, 16);

    private static final VoxelShape PILLAR_1 = Block.createCuboidShape(13, 0, 0, 16, 8, 3);
    private static final VoxelShape PILLAR_2 = Block.createCuboidShape(0, 0, 0, 3, 8, 3);
    private static final VoxelShape PILLAR_3 = Block.createCuboidShape(0, 0, 13, 3, 8, 16);
    private static final VoxelShape PILLAR_4 = Block.createCuboidShape(13, 0, 13, 16, 8, 16);

    private static final VoxelShape SHAPE = VoxelShapes.union(MAIN_PILLAR, PLATE, PILLAR_1, PILLAR_2, PILLAR_3, PILLAR_4);

    private final boolean inexhaustible;

    public ShopBlock(boolean inexhaustible) {
        super(FabricBlockSettings.create().nonOpaque().hardness(5.0f));
        this.inexhaustible = inexhaustible;
    }

    @Override
    public BlockRenderType getRenderType(BlockState state) {
        return BlockRenderType.MODEL;
    }

    @Override
    public VoxelShape getOutlineShape(BlockState state, BlockView world, BlockPos pos, ShapeContext context) {
        return SHAPE;
    }

    @Override
    public ActionResult onUse(BlockState state, World world, BlockPos pos, PlayerEntity player, Hand hand, BlockHitResult hit) {
        if (!world.isClient) {
            ShopBlockEntity shop = (ShopBlockEntity) world.getBlockEntity(pos);
            if (shop.busy) return ActionResult.SUCCESS;

            if (shop.getOwner().equals(player.getUuid()) && !player.isSneaking()) {
                player.openHandledScreen(state.createScreenHandlerFactory(world, pos));
                NumismaticOverhaul.CHANNEL.serverHandle(player).send(new UpdateShopScreenS2CPacket(shop));

                shop.busy = true;
            } else {
                ((ShopMerchant) shop.getMerchant()).updateTrades();
                shop.getMerchant().setCustomer(player);
                shop.getMerchant().sendOffers(player, Text.translatable("gui.numismatic-overhaul.shop.merchant_title"), 0);

                return ActionResult.SUCCESS;
            }
        }

        return ActionResult.SUCCESS;
    }

    @Override
    public void onPlaced(World world, BlockPos pos, BlockState state, @Nullable LivingEntity placer, ItemStack itemStack) {
        if (world.isClient) return;

        if (!(placer instanceof ServerPlayerEntity)) {
            world.breakBlock(pos, true);
            return;
        }

        if (itemStack.hasCustomName() && world.getBlockEntity(pos) instanceof ShopBlockEntity shop) {
            shop.setCustomName(itemStack.getName());
        }

        ((ShopBlockEntity) world.getBlockEntity(pos)).setOwner(placer.getUuid());
    }

    @Override
    public void onStateReplaced(BlockState state, World world, BlockPos pos, BlockState newState, boolean moved) {
        if (state.getBlock() != newState.getBlock()) {
            if (world.getBlockEntity(pos) instanceof ShopBlockEntity shop) {
                shop.getMerchant().setCustomer(null);

                CurrencyConverter.getAsValidStacks(shop.getStoredCurrency())
                        .forEach(stack -> ItemScatterer.spawn(shop.getWorld(), pos.getX(), pos.getY(), pos.getZ(), stack));

                ItemScatterer.spawn(world, pos, shop);
            }
            super.onStateReplaced(state, world, pos, newState, moved);
        }
    }

    public boolean inexhaustible() {
        return this.inexhaustible;
    }

    @Nullable
    @Override
    public BlockEntity createBlockEntity(BlockPos pos, BlockState state) {
        return new ShopBlockEntity(pos, state);
    }

    @Nullable
    @Override
    public <T extends BlockEntity> BlockEntityTicker<T> getTicker(World world, BlockState state, BlockEntityType<T> type) {
        return checkType(type, NumismaticOverhaulBlocks.Entities.SHOP, ShopBlockEntity::tick);
    }
}

package com.glisco.numismaticoverhaul.block.shop;

import com.glisco.numismaticoverhaul.NumismaticOverhaul;
import com.glisco.numismaticoverhaul.block.NumismaticOverhaulBlocks;
import io.wispforest.owo.ops.WorldOps;
import io.wispforest.owo.util.ImplementedInventory;
import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.minecraft.block.BlockState;
import net.minecraft.block.entity.LockableContainerBlockEntity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.entity.player.PlayerInventory;
import net.minecraft.inventory.Inventories;
import net.minecraft.inventory.SidedInventory;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.network.listener.ClientPlayPacketListener;
import net.minecraft.network.packet.Packet;
import net.minecraft.network.packet.s2c.play.BlockEntityUpdateS2CPacket;
import net.minecraft.screen.NamedScreenHandlerFactory;
import net.minecraft.screen.ScreenHandler;
import net.minecraft.text.Text;
import net.minecraft.util.collection.DefaultedList;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.Direction;
import net.minecraft.village.Merchant;
import net.minecraft.world.World;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.stream.IntStream;

public class ShopBlockEntity extends LockableContainerBlockEntity implements ImplementedInventory, SidedInventory, NamedScreenHandlerFactory {

    private static final int[] SLOTS = IntStream.range(0, 27).toArray();
    private static final int[] NO_SLOTS = new int[0];

    private final DefaultedList<ItemStack> INVENTORY = DefaultedList.ofSize(27, ItemStack.EMPTY);

    public boolean busy = false;
    private final Merchant merchant;
    private final List<ShopOffer> offers;

    private long storedCurrency;
    private UUID owner;
    private boolean allowsTransfer = false;

    private int tradeIndex;

    public ShopBlockEntity(BlockPos pos, BlockState state) {
        super(NumismaticOverhaulBlocks.Entities.SHOP, pos, state);

        boolean inexhaustible = (state.getBlock() instanceof ShopBlock shop) && shop.inexhaustible();
        this.merchant = new ShopMerchant(this, inexhaustible);

        this.offers = new ArrayList<>();
        this.storedCurrency = 0;
    }

    @Override
    public DefaultedList<ItemStack> getItems() {
        return INVENTORY;
    }

    @Override
    public int[] getAvailableSlots(Direction side) {
        return allowsTransfer ? SLOTS : NO_SLOTS;
    }

    @Override
    public boolean canInsert(int slot, ItemStack stack, @Nullable Direction dir) {
        return allowsTransfer;
    }

    @Override
    public boolean canExtract(int slot, ItemStack stack, Direction dir) {
        return false;
    }

    @Override
    protected Text getContainerName() {
        return Text.translatable("gui.numismatic-overhaul.shop.inventory_title");
    }

    @NotNull
    public Merchant getMerchant() {
        return merchant;
    }

    public List<ShopOffer> getOffers() {
        return offers;
    }

    public long getStoredCurrency() {
        return storedCurrency;
    }

    public boolean isTransferEnabled() {
        return allowsTransfer;
    }

    public void toggleTransfer() {
        this.allowsTransfer = !this.allowsTransfer;
    }

    public void setStoredCurrency(long storedCurrency) {
        this.storedCurrency = storedCurrency;
        markDirty();
    }

    public void addCurrency(long value) {
        this.storedCurrency += value;
        markDirty();
    }

    public void removeCurrency(int value) {
        this.storedCurrency -= value;
        markDirty();
    }

    @Override
    public void writeNbt(NbtCompound tag) {
        super.writeNbt(tag);
        Inventories.writeNbt(tag, INVENTORY);
        ShopOffer.writeAll(tag, offers);
        tag.putBoolean("AllowsTransfer", this.allowsTransfer);
        tag.putLong("StoredCurrency", storedCurrency);
        if (owner != null) {
            tag.putUuid("Owner", owner);
        }
    }

    @Override
    public void readNbt(NbtCompound tag) {
        super.readNbt(tag);
        Inventories.readNbt(tag, INVENTORY);
        ShopOffer.readAll(tag, offers);
        if (tag.contains("Owner")) {
            owner = tag.getUuid("Owner");
        }
        this.allowsTransfer = tag.getBoolean("AllowsTransfer");
        this.storedCurrency = tag.getLong("StoredCurrency");
    }

    public void addOrReplaceOffer(ShopOffer offer) {

        int indexToReplace = -1;

        for (int i = 0; i < offers.size(); i++) {
            if (!ItemStack.areEqual(offer.getSellStack(), offers.get(i).getSellStack())) continue;
            indexToReplace = i;
            break;
        }

        if (indexToReplace == -1) {
            if (offers.size() >= 24) {
                NumismaticOverhaul.LOGGER.error("Tried adding more than 24 trades to shop at {}", this.pos);
                return;
            }
            offers.add(offer);
        } else {
            offers.set(indexToReplace, offer);
        }

        this.markDirty();
    }

    public void deleteOffer(ItemStack stack) {
        if (!offers.removeIf(offer -> ItemStack.areEqual(stack, offer.getSellStack()))) {
            NumismaticOverhaul.LOGGER.error("Tried to delete invalid trade for {} from shop at {}", stack, this.pos);
            return;
        }

        this.markDirty();
    }

    public static void tick(World world, BlockPos pos, BlockState state, ShopBlockEntity blockEntity) {
        blockEntity.tick();
    }

    public void tick() {
        if (world.getTime() % 60 == 0) tradeIndex++;
    }

    @Environment(EnvType.CLIENT)
    public ItemStack getItemToRender() {
        if (tradeIndex > offers.size() - 1) tradeIndex = 0;
        return offers.get(tradeIndex).getSellStack();
    }

    @Override
    protected ScreenHandler createScreenHandler(int syncId, PlayerInventory playerInventory) {
        return new ShopScreenHandler(syncId, playerInventory, this);
    }

    @Override
    public boolean canPlayerUse(PlayerEntity player) {
        return player.getUuid().equals(this.owner) && this.world.getBlockEntity(this.pos) == this && this.pos.getSquaredDistance(player.getX(), player.getY(), player.getZ()) <= 100;
    }

    @Override
    public NbtCompound toInitialChunkDataNbt() {
        NbtCompound tag = new NbtCompound();
        this.writeNbt(tag);
        tag.remove("Items");
        tag.remove("StoredCurrency");
        return tag;
    }

    public UUID getOwner() {
        return owner;
    }

    public void setOwner(UUID owner) {
        this.owner = owner;
        markDirty();
    }

    @Nullable
    @Override
    public Packet<ClientPlayPacketListener> toUpdatePacket() {
        return BlockEntityUpdateS2CPacket.create(this);
    }

    @Override
    public void markDirty() {
        super.markDirty();
        WorldOps.updateIfOnServer(world, pos);
    }
}

package com.glisco.numismaticoverhaul.block.shop;

import com.glisco.numismaticoverhaul.currency.CurrencyHelper;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.item.ItemStack;
import net.minecraft.network.packet.s2c.play.SetTradeOffersS2CPacket;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.sound.SoundEvent;
import net.minecraft.sound.SoundEvents;
import net.minecraft.village.Merchant;
import net.minecraft.village.TradeOffer;
import net.minecraft.village.TradeOfferList;
import org.jetbrains.annotations.Nullable;

import java.util.Arrays;

public class ShopMerchant implements Merchant {

    private final ShopBlockEntity shop;
    private final boolean inexhaustible;
    private TradeOfferList recipeList = new TradeOfferList();
    private PlayerEntity customer;

    public ShopMerchant(ShopBlockEntity blockEntity, boolean inexhaustible) {
        this.shop = blockEntity;
        this.inexhaustible = inexhaustible;
    }

    public void updateTrades() {
        recipeList.clear();
        shop.getOffers().forEach(offer -> recipeList.add(offer.toTradeOffer(shop, this.inexhaustible)));
    }

    @Override
    public void setCustomer(@Nullable PlayerEntity customer) {
        this.customer = customer;
        this.shop.busy = customer != null;
    }

    @Nullable
    @Override
    public PlayerEntity getCustomer() {
        return customer;
    }

    @Override
    public TradeOfferList getOffers() {
        return recipeList;
    }

    @Override
    public void setOffersFromServer(@Nullable TradeOfferList offers) {
        this.recipeList = offers;
    }

    @Override
    public void trade(TradeOffer offer) {
        offer.use();
        if (!this.inexhaustible) {
            ShopOffer.remove(shop.getItems(), offer.getSellItem());

            this.updateTrades();
            if (this.getCustomer() instanceof ServerPlayerEntity serverPlayer) {
                serverPlayer.networkHandler.sendPacket(new SetTradeOffersS2CPacket(
                        serverPlayer.currentScreenHandler.syncId,
                        this.recipeList,
                        0, 0, false, false
                ));
            }
        }

        shop.addCurrency(CurrencyHelper.getValue(Arrays.asList(offer.getOriginalFirstBuyItem(), offer.getSecondBuyItem())));
    }

    @Override
    public void onSellingItem(ItemStack stack) {

    }

    @Override
    public int getExperience() {
        return 0;
    }

    @Override
    public void setExperienceFromServer(int experience) {

    }

    @Override
    public boolean isLeveledMerchant() {
        return false;
    }

    @Override
    public SoundEvent getYesSound() {
        return SoundEvents.ENTITY_VILLAGER_YES;
    }

    @Override
    public boolean isClient() {
        return false;
    }

    public ShopBlockEntity shop() {
        return this.shop;
    }
}

package com.glisco.numismaticoverhaul.block.shop;

import com.glisco.numismaticoverhaul.currency.CurrencyConverter;
import com.glisco.numismaticoverhaul.item.MoneyBagItem;
import com.glisco.numismaticoverhaul.villagers.data.NumismaticTradeOfferExtensions;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.nbt.NbtElement;
import net.minecraft.nbt.NbtList;
import net.minecraft.util.collection.DefaultedList;
import net.minecraft.village.TradeOffer;

import java.util.List;

public class ShopOffer {

    private final ItemStack sell;
    private final long price;

    public ShopOffer(ItemStack sell, long price) {

        if (sell.isEmpty()) throw new IllegalArgumentException("Sell Stack must not be empty");
        if (price == 0) throw new IllegalArgumentException("Price must not be null");

        this.sell = sell;
        this.price = price;
    }

    @SuppressWarnings("ConstantConditions")
    public TradeOffer toTradeOffer(ShopBlockEntity shop, boolean inexhaustible) {
        var buy = CurrencyConverter.getRequiredCurrencyTypes(price) == 1 ? CurrencyConverter.getAsItemStackList(price).get(0) : MoneyBagItem.create(price);
        int maxUses = inexhaustible ? Integer.MAX_VALUE : count(shop.getItems(), sell) / sell.getCount();

        final var tradeOffer = new TradeOffer(buy, sell, maxUses, 0, 0);
        ((NumismaticTradeOfferExtensions) tradeOffer).numismatic$setReputation(-69420);
        return tradeOffer;
    }

    public long getPrice() {
        return price;
    }

    public ItemStack getSellStack() {
        return sell.copy();
    }

    public static NbtCompound writeAll(NbtCompound tag, List<ShopOffer> offers) {

        NbtList offerList = new NbtList();

        for (ShopOffer offer : offers) {
            offerList.add(offer.toNbt());
        }

        tag.put("Offers", offerList);

        return tag;
    }

    public static void readAll(NbtCompound tag, List<ShopOffer> offers) {
        offers.clear();

        NbtList offerList = tag.getList("Offers", NbtElement.COMPOUND_TYPE);

        for (NbtElement offerTag : offerList) {
            offers.add(fromNbt((NbtCompound) offerTag));
        }
    }

    public NbtCompound toNbt() {
        var nbt = new NbtCompound();
        nbt.putLong("Price", this.price);

        var itemNbt = new NbtCompound();
        this.sell.writeNbt(itemNbt);

        nbt.put("Item", itemNbt);
        return nbt;
    }

    public static ShopOffer fromNbt(NbtCompound nbt) {
        var item = ItemStack.fromNbt(nbt.getCompound("Item"));
        return new ShopOffer(item, nbt.getLong("Price"));
    }

    public static int count(DefaultedList<ItemStack> stacks, ItemStack testStack) {
        int count = 0;
        for (var stack : stacks) {
            if (!ItemStack.canCombine(stack, testStack)) continue;
            count += stack.getCount();
        }
        return count;
    }

    public static int remove(DefaultedList<ItemStack> stacks, ItemStack removeStack) {
        int toRemove = removeStack.getCount();
        for (var stack : stacks) {
            if (!ItemStack.canCombine(stack, removeStack)) continue;

            int removed = stack.getCount();
            stack.decrement(toRemove);

            toRemove -= removed;
            if (toRemove < 1) break;
        }
        return removeStack.getCount() - toRemove;
    }

    @Override
    public String toString() {
        return this.sell + "@" + this.price + "coins";
    }
}

package com.glisco.numismaticoverhaul.block.shop;

import com.glisco.numismaticoverhaul.ModComponents;
import com.glisco.numismaticoverhaul.NumismaticOverhaul;
import com.glisco.numismaticoverhaul.client.gui.ShopScreen;
import com.glisco.numismaticoverhaul.network.ShopScreenHandlerRequestC2SPacket;
import com.glisco.numismaticoverhaul.network.UpdateShopScreenS2CPacket;
import io.wispforest.owo.client.screens.ScreenUtils;
import io.wispforest.owo.client.screens.SlotGenerator;
import io.wispforest.owo.client.screens.SyncedProperty;
import net.fabricmc.api.EnvType;
import net.fabricmc.api.Environment;
import net.minecraft.client.MinecraftClient;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.entity.player.PlayerInventory;
import net.minecraft.inventory.Inventory;
import net.minecraft.inventory.SimpleInventory;
import net.minecraft.item.ItemStack;
import net.minecraft.screen.ScreenHandler;
import net.minecraft.screen.slot.Slot;

import java.util.ArrayList;
import java.util.List;

public class ShopScreenHandler extends ScreenHandler {

    private final PlayerEntity owner;

    private final Inventory shopInventory;
    private final SyncedProperty<ItemStack> tradeEditBuffer;

    private final List<ShopOffer> offers;

    private ShopBlockEntity shop = null;

    public ShopScreenHandler(int syncId, PlayerInventory playerInventory) {
        this(syncId, playerInventory, new SimpleInventory(27));
    }

    public ShopScreenHandler(int syncId, PlayerInventory playerInventory, Inventory shopInventory) {
        super(NumismaticOverhaul.SHOP_SCREEN_HANDLER_TYPE, syncId);
        this.shopInventory = shopInventory;
        this.owner = playerInventory.player;

        if (!this.owner.getWorld().isClient) {
            this.shop = (ShopBlockEntity) shopInventory;
            this.offers = shop.getOffers();
        } else {
            this.offers = new ArrayList<>();
        }

        SlotGenerator.begin(this::addSlot, 8, 17)
                .slotFactory((inv, index, x, y) -> new AutoHidingSlot(inv, index, x, y, 0, false))
                .grid(this.shopInventory, 0, 9, 3)
                .slotFactory(Slot::new)
                .moveTo(8, 85)
                .playerInventory(playerInventory);

        this.tradeEditBuffer = this.createProperty(ItemStack.class, ItemStack.EMPTY);
        this.tradeEditBuffer.observe(stack -> {
            if (this.owner.getWorld().isClient && MinecraftClient.getInstance().currentScreen instanceof ShopScreen screen) {
                screen.afterDataUpdate();
            }
        });
    }

    @Override
    public boolean canUse(PlayerEntity player) {
        return this.shopInventory.canPlayerUse(player);
    }

    public void loadOffer(long index) {
        if (!this.owner.getWorld().isClient) {
            if (index > this.offers.size() - 1) {
                NumismaticOverhaul.LOGGER.error("Player {} attempted to load invalid trade at index {}", owner.getName(), index);
                return;
            }

            this.tradeEditBuffer.set(this.offers.get((int) index).getSellStack());
        } else {
            NumismaticOverhaul.CHANNEL.clientHandle().send(new ShopScreenHandlerRequestC2SPacket(ShopScreenHandlerRequestC2SPacket.Action.LOAD_OFFER, index));
        }
    }

    public void createOffer(long price) {
        if (!this.owner.getWorld().isClient) {
            final var stack = this.tradeEditBuffer.get();
            if (stack.isEmpty()) return;

            this.shop.addOrReplaceOffer(new ShopOffer(stack, price));
            this.updateClient();
        } else {
            NumismaticOverhaul.CHANNEL.clientHandle().send(new ShopScreenHandlerRequestC2SPacket(ShopScreenHandlerRequestC2SPacket.Action.CREATE_OFFER, price));
        }
    }

    public void extractCurrency() {
        if (!this.owner.getWorld().isClient) {
            ModComponents.CURRENCY.get(owner).modify(shop.getStoredCurrency());
            this.shop.setStoredCurrency(0);
            this.updateClient();
        } else {
            NumismaticOverhaul.CHANNEL.clientHandle().send(new ShopScreenHandlerRequestC2SPacket(ShopScreenHandlerRequestC2SPacket.Action.EXTRACT_CURRENCY));
        }
    }

    public void deleteOffer() {
        if (!this.owner.getWorld().isClient) {
            this.shop.deleteOffer(this.tradeEditBuffer.get());
            this.updateClient();
        } else {
            NumismaticOverhaul.CHANNEL.clientHandle().send(new ShopScreenHandlerRequestC2SPacket(ShopScreenHandlerRequestC2SPacket.Action.DELETE_OFFER));
        }
    }

    public void toggleTransfer() {
        if (!this.owner.getWorld().isClient) {
            this.shop.toggleTransfer();
            this.updateClient();
        } else {
            NumismaticOverhaul.CHANNEL.clientHandle().send(new ShopScreenHandlerRequestC2SPacket(ShopScreenHandlerRequestC2SPacket.Action.TOGGLE_TRANSFER));
        }
    }

    public void handleBufferClick() {
        if (!this.owner.getWorld().isClient) {
            this.tradeEditBuffer.set(this.getCursorStack().copy());
        } else {
            NumismaticOverhaul.CHANNEL.clientHandle().send(new ShopScreenHandlerRequestC2SPacket(ShopScreenHandlerRequestC2SPacket.Action.CLICK_BUFFER));
        }
    }

    private void updateClient() {
        NumismaticOverhaul.CHANNEL.serverHandle(owner).send(new UpdateShopScreenS2CPacket(shop));
    }

    public ItemStack getBufferStack() {
        return this.tradeEditBuffer.get();
    }

    @Override
    public ItemStack quickMove(PlayerEntity player, int invSlot) {
        return ScreenUtils.handleSlotTransfer(this, invSlot, this.shopInventory.size());
    }

    @Override
    public void onClosed(PlayerEntity player) {
        super.onClosed(player);
        if (this.shop != null) this.shop.busy = false;
    }

    private static class AutoHidingSlot extends Slot {

        private final int targetTab;
        private final boolean hide;

        public AutoHidingSlot(Inventory inventory, int index, int x, int y, int targetTab, boolean hide) {
            super(inventory, index, x, y);
            this.targetTab = targetTab;
            this.hide = hide;
        }

        @Override
        @Environment(EnvType.CLIENT)
        public boolean isEnabled() {
            if (!(MinecraftClient.getInstance().currentScreen instanceof ShopScreen screen)) return true;
            //noinspection SimplifiableConditionalExpression
            return hide
                    ? screen.tab() != targetTab
                    : screen.tab() == targetTab;
        }
    }
}

package com.glisco.numismaticoverhaul.currency;

import com.glisco.numismaticoverhaul.ModComponents;
import com.glisco.numismaticoverhaul.NumismaticOverhaul;
import com.glisco.numismaticoverhaul.NumismaticOverhaulConfigModel;
import com.glisco.numismaticoverhaul.item.CoinItem;
import dev.onyxstudios.cca.api.v3.component.Component;
import dev.onyxstudios.cca.api.v3.component.sync.AutoSyncedComponent;
import io.wispforest.owo.config.ConfigSynchronizer;
import io.wispforest.owo.config.Option;
import io.wispforest.owo.ops.TextOps;
import io.wispforest.owo.ui.core.Color;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.text.Text;
import net.minecraft.util.Formatting;

import java.util.ArrayList;
import java.util.List;

public class CurrencyComponent implements Component, AutoSyncedComponent {

    private long value;
    private final PlayerEntity provider;

    private final List<Long> transactions;

    public CurrencyComponent(PlayerEntity provider) {
        this.provider = provider;
        this.transactions = new ArrayList<Long>();
    }

    @Override
    public void readFromNbt(NbtCompound tag) {
        value = tag.getLong("Value");
    }

    @Override
    public void writeToNbt(NbtCompound tag) {
        tag.putLong("Value", value);
    }

    public long getValue() {
        return value;
    }

    /**
     * This is only to be used in specific edge cases
     * <br>
     * Use {@link CurrencyComponent#modify(long)} or the transaction system wherever possible
     */
    @Deprecated
    public void setValue(long value) {
        this.value = value;

        //Update Client
        if (!provider.getWorld().isClient) {
            ModComponents.CURRENCY.sync(this.provider);
        }
    }

    /**
     * Modifies this component, displays a message with the change
     *
     * @param value The value to modify by
     */
    public void modify(long value) {
        // This code can be triggered on both Client and Server, for example via Money Bags
        setValue(this.value + value);

        long tempValue = value < 0 ? -value : value;

        List<ItemStack> transactionStacks = CurrencyConverter.getAsItemStackList(tempValue);
        if (transactionStacks.isEmpty()) return;


        // Only do text handling on the server, this is to prevent duplicate text if the config is set to display in chat
        if (provider.getWorld().isClient()) return;

        // Always try to respect the clients option on where they want the message
        NumismaticOverhaulConfigModel.MoneyMessageLocation moneyMessageLocation;

        moneyMessageLocation = (NumismaticOverhaulConfigModel.MoneyMessageLocation) ConfigSynchronizer.getClientOptions(
                (ServerPlayerEntity) provider,
                NumismaticOverhaul.CONFIG
        ).get(NumismaticOverhaul.CONFIG.keys.moneyMessageLocation);

        if (moneyMessageLocation == NumismaticOverhaulConfigModel.MoneyMessageLocation.DISABLED) return;

        // Text handling examples:
        // Actionbar = "+ [12 Silver, 4 Bronze]"
        // Chat = "numismatic > + [12 Silver, 4 Bronze]"
        var message = moneyMessageLocation == NumismaticOverhaulConfigModel.MoneyMessageLocation.CHAT
                ?
                TextOps.withColor("numismatic §> ", Currency.GOLD.getNameColor(), Color.ofFormatting(Formatting.GRAY).argb())
                :
                Text.empty();

        message.append(value < 0 ? Text.literal("§c- ") : Text.literal("§a+ "));
        message.append(Text.literal("§7["));
        for (ItemStack stack : transactionStacks) {
            message.append(Text.literal("§b" + stack.getCount() + " "));
            message.append(TextOps.translateWithColor(
                    "currency.numismatic-overhaul." + ((CoinItem) stack.getItem()).currency.name().toLowerCase(),
                    ((CoinItem) stack.getItem()).currency.getNameColor()
            ));

            if (transactionStacks.indexOf(stack) != transactionStacks.size() - 1) {
                message.append(Text.literal(", "));
            }
        }
        message.append(Text.literal("§7]"));

        provider.sendMessage(message, moneyMessageLocation == NumismaticOverhaulConfigModel.MoneyMessageLocation.ACTIONBAR);

    }

    /**
     * Same as {@link CurrencyComponent#modify(long)}, but doesn't show a message in the action bar
     *
     * @param value The value to modify by
     */
    public void silentModify(long value) {
        setValue(this.value + value);
    }

    /**
     * Enqueues a transaction onto the stack
     *
     * @param value The value this component should be modified by
     */
    public void pushTransaction(long value) {
        this.transactions.add(value);
    }

    /**
     * Pops the most recent transaction off the stack
     *
     * @return The transaction that was popped
     */
    public Long popTransaction() {
        return this.transactions.remove(this.transactions.size() - 1);
    }

    /**
     * Commits the transactions on the current stack into the actual component value and pops the entire stack
     * <br>
     * Displays one accumulated action bar message
     */
    public void commitTransactions() {
        this.modify(this.transactions.stream().mapToLong(Long::longValue).sum());
        this.transactions.clear();
    }
}

package com.glisco.numismaticoverhaul.currency;

import com.glisco.numismaticoverhaul.item.NumismaticOverhaulItems;
import net.minecraft.item.ItemStack;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class CurrencyConverter {

    /**
     * @return An array of 3 {@link ItemStack}, format ItemStack[]{BRONZE, SILVER, GOLD}, stack sizes can exceed 99
     */
    public static ItemStack[] getAsItemStackArray(long value) {
        ItemStack[] output = new ItemStack[]{null, null, null};

        long[] values = CurrencyResolver.splitValues(value);

        output[2] = new ItemStack(NumismaticOverhaulItems.GOLD_COIN, asInt(values[2]));
        output[1] = new ItemStack(NumismaticOverhaulItems.SILVER_COIN, asInt(values[1]));
        output[0] = new ItemStack(NumismaticOverhaulItems.BRONZE_COIN, asInt(values[0]));

        return output;
    }

    /**
     * Wrapper for {@link #getAsItemStackArray(long)} that only includes non-zero {@link ItemStack}
     *
     * @return A list of {@link ItemStack}, stack sizes can exceed 99
     */
    public static List<ItemStack> getAsItemStackList(long value) {
        List<ItemStack> list = new ArrayList<>();

        Arrays.stream(getAsItemStackArray(value)).forEach(itemStack -> {
            if (itemStack.getCount() != 0) list.add(0, itemStack);
        });

        return list;
    }

    /**
     * Wrapper for {@link #getAsItemStackArray(long)} that only includes non-zero {@link ItemStack}
     *
     * @return A list of {@link ItemStack}, stack sizes can exceed 99
     */
    public static List<ItemStack> getAsItemStackList(long[] values) {
        List<ItemStack> list = new ArrayList<>();

        for (int i = 0; i < values.length; i++) {
            if (values[i] <= 0) continue;
            list.add(0, new ItemStack(Currency.values()[i], asInt(values[i])));
        }

        return list;
    }

    /**
     * @return The amount of currency types required to represent this stack's raw value
     */
    public static int getRequiredCurrencyTypes(long value) {
        return splitAtMaxCount(getAsItemStackList(value)).size();
    }

    /**
     * Splits the provided list into another list where no stacks are over their max size
     *
     * @param input A list of {@link ItemStack} that could contain some with illegal sizes
     * @return A list where no stacks have illegal sizes, most likely bigger than input
     */
    public static List<ItemStack> splitAtMaxCount(List<ItemStack> input) {
        List<ItemStack> output = new ArrayList<>();

        for (ItemStack stack : input) {
            if (stack.getCount() <= stack.getMaxCount()) {
                output.add(stack);
            } else {
                for (int i = 0; i < stack.getCount() / stack.getMaxCount(); i++) {
                    ItemStack copy = stack.copy();
                    copy.setCount(stack.getMaxCount());
                    output.add(copy);
                }

                ItemStack copy = stack.copy();
                copy.setCount(stack.getCount() % stack.getMaxCount());
                output.add(copy);
            }
        }

        return output;
    }

    public static List<ItemStack> getAsValidStacks(long value) {
        return splitAtMaxCount(getAsItemStackList(value));
    }

    public static List<ItemStack> getAsValidStacks(long[] values) {
        return splitAtMaxCount(getAsItemStackList(values));
    }

    public static int asInt(long value) {
        return value > Integer.MAX_VALUE ? Integer.MAX_VALUE : (int) value;
    }

}

package com.glisco.numismaticoverhaul.currency;

import com.glisco.numismaticoverhaul.item.CoinItem;
import com.glisco.numismaticoverhaul.item.CurrencyItem;
import com.glisco.numismaticoverhaul.item.MoneyBagItem;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.nbt.NbtElement;

import java.util.ArrayList;
import java.util.List;

public class CurrencyHelper {

    /**
     * Checks how much money a player has as coin items in their inventory
     *
     * @param player The player to operate on (duh)
     * @param remove Whether to remove all coins from the player in the process
     * @return The amount of currency contained in the player's inventory
     */
    public static long getMoneyInInventory(PlayerEntity player, boolean remove) {

        long value = 0;

        for (int i = 0; i < player.getInventory().size(); i++) {
            ItemStack stack = player.getInventory().getStack(i);
            if (isCombined(stack)) continue;
            if (!(stack.getItem() instanceof CurrencyItem currencyItem)) continue;

            value += currencyItem.getValue(stack);

            if (remove) player.getInventory().removeOne(stack);
        }

        return value;
    }

    public static int getValue(List<ItemStack> stacks) {
        return stacks.stream().mapToInt(stack -> {
            if (stack == null) return 0;

            if (isCombined(stack)) return 0;
            if (!(stack.getItem() instanceof CurrencyItem currencyItem)) return 0;
            return (int) currencyItem.getValue(stack);
        }).sum();
    }

    public static void offerAsCoins(PlayerEntity player, long value) {
        for (ItemStack itemStack : CurrencyConverter.getAsValidStacks(value)) {
            player.getInventory().offerOrDrop(itemStack);
        }
    }

    public static boolean deductFromInventory(PlayerEntity player, long value) {
        long presentInInventory = getMoneyInInventory(player, false);
        if (presentInInventory < value) return false;

        getMoneyInInventory(player, true);

        offerAsCoins(player, presentInInventory - value);
        return true;
    }

    /**
     * Converts an amount of currency to a list of {@link ItemStack},
     * prefers {@link CoinItem} but may fall back to {@link MoneyBagItem}
     *
     * @param value     The currency value to convert
     * @param maxStacks The maximum amount of stacks the result may have
     * @return The List of {@link ItemStack}
     */
    public static List<ItemStack> getAsStacks(long value, int maxStacks) {

        List<ItemStack> stacks = new ArrayList<>();
        List<ItemStack> rawStacks = CurrencyConverter.getAsValidStacks(value);

        if (rawStacks.size() <= maxStacks) {
            stacks.addAll(rawStacks);
        } else {
            stacks.add(MoneyBagItem.create(value));
        }

        return stacks;
    }

    public static ItemStack getClosest(long value) {
        long[] values = CurrencyResolver.splitValues(value);

        for (int i = 0; i < 2; i++) {
            if (values[i + 1] == 0) break;
            values[i + 1] += Math.round(values[i] / 100f);
            values[i] = 0;
        }

        return CurrencyConverter.getAsItemStackList(CurrencyResolver.combineValues(values)).get(0);
    }

    public static long[] getFromNbt(NbtCompound nbt, String key) {
        if (nbt.contains(key, NbtElement.LONG_ARRAY_TYPE)) return nbt.getLongArray(key).clone();
        if (!nbt.contains(key, NbtElement.INT_ARRAY_TYPE)) return new long[0];

        var intArray = nbt.getIntArray(key);
        var longArray = new long[intArray.length];
        for (int i = 0; i < intArray.length; i++) {
            longArray[i] = intArray[i];
        }

        return longArray;
    }

    private static boolean isCombined(ItemStack stack) {
        return stack.hasNbt() && stack.getNbt().has(MoneyBagItem.COMBINED);
    }
}

package com.glisco.numismaticoverhaul.currency;

import com.glisco.numismaticoverhaul.NumismaticOverhaul;

public class CurrencyResolver {

    /**
     * Splits the given raw value into the individual currencies, MSD first
     *
     * @param rawValue The value to split
     * @return The individual currency values in the format int[]{BRONZE, SILVER, GOLD}
     */
    public static long[] splitValues(long rawValue) {
        long[] output = new long[]{0, 0, 0};

        if (rawValue / 10000 != 0) {
            output[2] = rawValue / 10000;
            rawValue -= 10000 * output[2];
        }

        if (rawValue / 100 != 0) {
            output[1] = rawValue / 100;
            rawValue -= 100 * output[1];
        }

        if (rawValue > 0) {
            output[0] = rawValue;
        }

        return output;
    }

    /**
     * Combines the given values in a raw currency value
     *
     * @param values The individual currency values in the format int[]{BRONZE, SILVER, GOLD}
     * @return The raw value, with respect to each value's worth
     */
    public static long combineValues(long[] values) {
        if (values.length != 3) {
            NumismaticOverhaul.LOGGER.error(
                "Invalid money bag!",
                new IllegalArgumentException("Input array has to have 3 elements")
            );
            return 0L;
        }

        return values[0] + values[1] * 100 + values[2] * 10000;
    }

}

package com.glisco.numismaticoverhaul.item;

import com.glisco.numismaticoverhaul.ModComponents;
import com.glisco.numismaticoverhaul.NumismaticOverhaul;
import com.glisco.numismaticoverhaul.currency.Currency;
import io.wispforest.owo.itemgroup.OwoItemSettings;
import net.minecraft.client.item.TooltipData;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.inventory.StackReference;
import net.minecraft.item.Item;
import net.minecraft.item.ItemStack;
import net.minecraft.screen.slot.Slot;
import net.minecraft.screen.slot.TradeOutputSlot;
import net.minecraft.text.Style;
import net.minecraft.text.Text;
import net.minecraft.text.TextColor;
import net.minecraft.util.ClickType;
import net.minecraft.util.Hand;
import net.minecraft.util.TypedActionResult;
import net.minecraft.world.World;

import java.util.Optional;

public class CoinItem extends Item implements CurrencyItem {

    public final Currency currency;
    public final Style NAME_STYLE;

    public CoinItem(Currency currency) {
        super(new OwoItemSettings().group(NumismaticOverhaul.NUMISMATIC_GROUP).maxCount(99));
        this.currency = currency;
        this.NAME_STYLE = Style.EMPTY.withColor(TextColor.fromRgb(currency.getNameColor()));
    }

    @Override
    public boolean onClicked(ItemStack clickedStack, ItemStack otherStack, Slot slot, ClickType clickType, PlayerEntity player, StackReference cursorStackReference) {
        if (slot instanceof TradeOutputSlot) return false;
        if (clickType != ClickType.LEFT) return false;

        if ((otherStack.getItem() == this && otherStack.getCount() + clickedStack.getCount() <= otherStack.getMaxCount()) || !(otherStack.getItem() instanceof CurrencyItem currencyItem))
            return false;

        long[] values = currencyItem.getCombinedValue(otherStack);
        values[this.currency.ordinal()] += clickedStack.getCount();

        final var stack = MoneyBagItem.createCombined(values);
        if (!slot.canInsert(stack)) return false;

        slot.setStack(stack);
        cursorStackReference.set(ItemStack.EMPTY);

        return true;
    }

    @Override
    public TypedActionResult<ItemStack> use(World world, PlayerEntity user, Hand hand) {

        ItemStack clickedStack = user.getStackInHand(hand);
        long rawValue = ((CoinItem) clickedStack.getItem()).currency.getRawValue(clickedStack.getCount());

        if (!world.isClient) {
            ModComponents.CURRENCY.get(user).modify(rawValue);
        }

        return TypedActionResult.success(ItemStack.EMPTY);
    }

    @Override
    public Optional<TooltipData> getTooltipData(ItemStack stack) {
        return Optional.of(new CurrencyTooltipData(this.currency.getRawValue(stack.getCount()),
                CurrencyItem.hasOriginalValue(stack) ? CurrencyItem.getOriginalValue(stack) : -1));
    }

    @Override
    public Text getName() {
        return super.getName().copy().setStyle(NAME_STYLE);
    }

    @Override
    public Text getName(ItemStack stack) {
        return super.getName(stack).copy().setStyle(NAME_STYLE);
    }

    @Override
    public boolean wasAdjusted(ItemStack other) {
        return other.getItem() != this;
    }

    @Override
    public long getValue(ItemStack stack) {
        return this.currency.getRawValue(stack.getCount());
    }

    @Override
    public long[] getCombinedValue(ItemStack stack) {
        final long[] values = new long[3];
        values[this.currency.ordinal()] = stack.getCount();
        return values;
    }
}

package com.glisco.numismaticoverhaul.item;

import io.wispforest.owo.nbt.NbtKey;
import net.minecraft.item.ItemStack;

public interface CurrencyItem {

    NbtKey<Long> ORIGINAL_VALUE = new NbtKey<>("OriginalValue", NbtKey.Type.LONG);

    static void setOriginalValue(ItemStack stack, long value) {
        stack.put(ORIGINAL_VALUE, value);
    }

    static long getOriginalValue(ItemStack stack) {
        return stack.get(ORIGINAL_VALUE);
    }

    static boolean hasOriginalValue(ItemStack stack) {
        return stack.has(ORIGINAL_VALUE);
    }

    boolean wasAdjusted(ItemStack other);

    long getValue(ItemStack stack);

    long[] getCombinedValue(ItemStack stack);

}

package com.glisco.numismaticoverhaul.item;

import com.glisco.numismaticoverhaul.ModComponents;
import com.glisco.numismaticoverhaul.currency.CurrencyConverter;
import com.glisco.numismaticoverhaul.currency.CurrencyResolver;
import io.wispforest.owo.nbt.NbtKey;
import net.minecraft.client.item.TooltipData;
import net.minecraft.entity.Entity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.inventory.StackReference;
import net.minecraft.item.Item;
import net.minecraft.item.ItemStack;
import net.minecraft.screen.slot.Slot;
import net.minecraft.screen.slot.TradeOutputSlot;
import net.minecraft.text.Text;
import net.minecraft.util.ClickType;
import net.minecraft.util.Hand;
import net.minecraft.util.TypedActionResult;
import net.minecraft.world.World;

import java.util.Optional;

public class MoneyBagItem extends Item implements CurrencyItem {

    private static final NbtKey<Long> VALUE = new NbtKey<>("Value", NbtKey.Type.LONG);
    private static final NbtKey<long[]> VALUES = new NbtKey<>("Values", NbtKey.Type.LONG_ARRAY);
    public static final NbtKey<Boolean> COMBINED = new NbtKey<>("Combined", NbtKey.Type.BOOLEAN);

    public MoneyBagItem() {
        super(new Settings().maxCount(1));
    }

    @Override
    public ItemStack getDefaultStack() {
        var defaultStack = super.getDefaultStack();
        defaultStack.put(VALUE, 0L);
        return defaultStack;
    }

    public static ItemStack create(long value) {
        var stack = new ItemStack(NumismaticOverhaulItems.MONEY_BAG);
        stack.put(VALUE, value);
        return stack;
    }

    public static ItemStack createCombined(long[] values) {
        var stack = new ItemStack(NumismaticOverhaulItems.MONEY_BAG);
        stack.put(VALUES, values);
        stack.put(COMBINED, true);
        return stack;
    }

    public long getValue(ItemStack stack) {
        if (stack.getItem() != NumismaticOverhaulItems.MONEY_BAG) return 0;

        if (!stack.has(COMBINED)) {
            return stack.get(VALUE);
        } else {
            return CurrencyResolver.combineValues(stack.get(VALUES));
        }
    }

    @Override
    public long[] getCombinedValue(ItemStack stack) {
        if (!stack.has(COMBINED)) {
            return CurrencyResolver.splitValues(stack.get(VALUE));
        } else {
            return stack.get(VALUES);
        }
    }

    public void setValue(ItemStack stack, long value) {
        stack.getOrCreateNbt().put(VALUE, value);
    }

    public void setCombinedValue(ItemStack stack, long[] values) {
        stack.getOrCreateNbt().put(VALUES, values);
    }

    @Override
    public boolean onClicked(ItemStack clickedStack, ItemStack otherStack, Slot slot, ClickType clickType, PlayerEntity player, StackReference cursorStackReference) {
        if (slot instanceof TradeOutputSlot) return false;

        if (clickType == ClickType.RIGHT && clickedStack.getItem() == this && otherStack.isEmpty()) {
            final var stackRepresentation = CurrencyConverter.getAsValidStacks(getCombinedValue(clickedStack));
            if (stackRepresentation.isEmpty()) return false;

            final var coinStack = stackRepresentation.get(0);
            cursorStackReference.set(coinStack);

            final long[] values = getCombinedValue(clickedStack);
            values[((CoinItem) coinStack.getItem()).currency.ordinal()] -= coinStack.getCount();

            final long newValue = CurrencyResolver.combineValues(values);
            final boolean canBeCompacted = values[0] < 100 && values[1] < 100 && values[2] < 100;

            if (newValue == 0) {
                slot.setStack(ItemStack.EMPTY);
            } else if (canBeCompacted && CurrencyConverter.getAsValidStacks(newValue).size() == 1) {
                slot.setStack(CurrencyConverter.getAsValidStacks(newValue).get(0));
            } else {
                setCombinedValue(clickedStack, values);
            }

        } else if (clickType == ClickType.LEFT) {
            if (!(otherStack.getItem() instanceof CurrencyItem currencyItem)) return false;

            long[] clickedValues = getCombinedValue(clickedStack);
            long[] otherValues = currencyItem.getCombinedValue(otherStack);

            for (int i = 0; i < clickedValues.length; i++) clickedValues[i] += otherValues[i];

            final var stack = MoneyBagItem.createCombined(clickedValues);
            if (!slot.canInsert(stack)) return false;

            slot.setStack(stack);
            cursorStackReference.set(ItemStack.EMPTY);
        }

        return true;
    }

    @Override
    public Optional<TooltipData> getTooltipData(ItemStack stack) {
        return Optional.of(new CurrencyTooltipData(this.getCombinedValue(stack),
                CurrencyItem.hasOriginalValue(stack) ? CurrencyResolver.splitValues(CurrencyItem.getOriginalValue(stack)) : new long[]{-1}));
    }

    @Override
    public void inventoryTick(ItemStack stack, World world, Entity entity, int slot, boolean selected) {
        if (stack.get(COMBINED)) return;
        if (!(entity instanceof PlayerEntity player)) return;

        player.getInventory().removeOne(stack);

        for (ItemStack toOffer : CurrencyConverter.getAsValidStacks(getValue(stack))) {
            player.getInventory().offerOrDrop(toOffer);
        }
    }

    @Override
    public TypedActionResult<ItemStack> use(World world, PlayerEntity user, Hand hand) {
        ModComponents.CURRENCY.get(user).modify(getValue(user.getStackInHand(hand)));
        user.setStackInHand(hand, ItemStack.EMPTY);
        return TypedActionResult.success(ItemStack.EMPTY);
    }

    @Override
    public boolean wasAdjusted(ItemStack other) {
        return true;
    }

    @Override
    public Text getName() {
        return super.getName().copy().setStyle(NumismaticOverhaulItems.SILVER_COIN.NAME_STYLE);
    }

}

package com.glisco.numismaticoverhaul.mixin;

import com.glisco.numismaticoverhaul.ModComponents;
import com.glisco.numismaticoverhaul.block.shop.ShopMerchant;
import com.glisco.numismaticoverhaul.currency.CurrencyComponent;
import com.glisco.numismaticoverhaul.currency.CurrencyHelper;
import com.glisco.numismaticoverhaul.item.CoinItem;
import com.glisco.numismaticoverhaul.item.NumismaticOverhaulItems;
import net.minecraft.entity.Entity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.entity.player.PlayerInventory;
import net.minecraft.item.ItemStack;
import net.minecraft.screen.MerchantScreenHandler;
import net.minecraft.village.Merchant;
import org.spongepowered.asm.mixin.Final;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Shadow;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;

@Mixin(MerchantScreenHandler.class)
public class MerchantScreenHandlerMixin {

    @Shadow
    @Final
    private Merchant merchant;

    //Autofill with coins from the player's purse if the trade requires it
    //Injected at TAIL to let normal autofill run and fill up if anything is missing
    @Inject(method = "autofill", at = @At("TAIL"))
    public void autofillOverride(int slot, ItemStack stack, CallbackInfo ci) {
        MerchantScreenHandler handler = (MerchantScreenHandler) (Object) this;
        CurrencyComponent playerBalance = ModComponents.CURRENCY.get(((PlayerInventory) handler.getSlot(3).inventory).player);

        if (stack.getItem() instanceof CoinItem) {
            numismatic$autofillWithCoins(slot, stack, handler, playerBalance);
        } else if (stack.getItem() == NumismaticOverhaulItems.MONEY_BAG) {
            autofillWithMoneyBag(slot, stack, handler, playerBalance);
        }

        if (slot == 1) playerBalance.commitTransactions();
    }

    private static void numismatic$autofillWithCoins(int slot, ItemStack stack, MerchantScreenHandler handler, CurrencyComponent playerBalance) {
        //See how much is required and how much was already autofilled
        long requiredCurrency = ((CoinItem) stack.getItem()).currency.getRawValue(stack.getCount());
        long presentCurrency = ((CoinItem) stack.getItem()).currency.getRawValue(handler.getSlot(slot).getStack().getCount());

        if (requiredCurrency <= presentCurrency) return;

        //Find out how much we still need to fill
        long neededCurrency = requiredCurrency - presentCurrency;

        //Is that even possible?
        if (!(neededCurrency <= playerBalance.getValue())) return;

        playerBalance.pushTransaction(-neededCurrency);

        handler.slots.get(slot).setStack(stack.copy());
    }

    private static void autofillWithMoneyBag(int slot, ItemStack stack, MerchantScreenHandler handler, CurrencyComponent playerBalance) {
        if (ItemStack.canCombine(stack, handler.getSlot(slot).getStack())) return;
        PlayerEntity player = ((PlayerInventory) handler.getSlot(3).inventory).player;

        //See how much is required and how much in present in the player's inventory
        long requiredCurrency = NumismaticOverhaulItems.MONEY_BAG.getValue(stack);
        long availableCurrencyInPlayerInventory = CurrencyHelper.getMoneyInInventory(player, false);

        //Find out how much we still need to fill
        long neededCurrency = requiredCurrency - availableCurrencyInPlayerInventory;

        //Is that even possible?
        if (neededCurrency > playerBalance.getValue()) return;

        if (neededCurrency <= 0) {
            CurrencyHelper.deductFromInventory(player, requiredCurrency);
        } else {
            CurrencyHelper.deductFromInventory(player, availableCurrencyInPlayerInventory);
            playerBalance.pushTransaction(-neededCurrency);
        }

        handler.slots.get(slot).setStack(stack.copy());
    }

    @Inject(method = "playYesSound", at = @At("HEAD"), cancellable = true)
    public void checkForEntityOnYes(CallbackInfo ci) {
        if (!(merchant instanceof Entity)) ci.cancel();
    }

    @Inject(method = "canUse", at = @At("HEAD"), cancellable = true)
    public void thwartTaxEvasion(PlayerEntity player, CallbackInfoReturnable<Boolean> cir) {
        if (!(this.merchant instanceof ShopMerchant shopMerchant)) return;

        var shop = shopMerchant.shop();
        if (shop.getWorld().getBlockEntity(shop.getPos()) != shop || shop.getPos().getSquaredDistance(player.getX(), player.getY(), player.getZ()) > 100) {
            cir.setReturnValue(false);
        }
    }

}

package com.glisco.numismaticoverhaul.mixin;

import com.glisco.numismaticoverhaul.ModComponents;
import com.glisco.numismaticoverhaul.NumismaticOverhaul;
import com.glisco.numismaticoverhaul.currency.CurrencyConverter;
import io.wispforest.owo.ops.ItemOps;
import net.minecraft.entity.player.PlayerEntity;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;

@Mixin(PlayerEntity.class)
public class ServerPlayerEntityMixin {

    @Inject(method = "vanishCursedItems", at = @At("TAIL"))
    public void onServerDeath(CallbackInfo ci) {
        var player = (PlayerEntity) (Object) this;

        final var world = player.getWorld();
        if (world.isClient) return;

        final var component = ModComponents.CURRENCY.get(player);

        var dropPercentage = world.getGameRules().get(NumismaticOverhaul.MONEY_DROP_PERCENTAGE).get() * .01f;
        int dropped = (int) (component.getValue() * dropPercentage);

        var stacksDropped = CurrencyConverter.getAsValidStacks(dropped);
        for (var drop : stacksDropped) {
            for (int i = 0; i < drop.getCount(); i++) {
                player.dropItem(ItemOps.singleCopy(drop), true, false);
            }
        }

        component.modify(-dropped);
    }

}

package com.glisco.numismaticoverhaul.network;

import com.glisco.numismaticoverhaul.block.pawn.PawnShopScreenHandler;
import com.glisco.numismaticoverhaul.block.shop.ShopScreenHandler;
import io.wispforest.owo.network.ServerAccess;

public record PawnShopScreenHandlerRequestC2SPacket(Action action, long value) {

    public PawnShopScreenHandlerRequestC2SPacket(Action action) {
        this(action, 0);
    }

    public static void handle(PawnShopScreenHandlerRequestC2SPacket message, ServerAccess access) {
        final var player = access.player();
        final long value = message.value();

        if (!(player.currentScreenHandler instanceof PawnShopScreenHandler shopHandler)) return;

        switch (message.action()) {
            case LOAD_OFFER -> shopHandler.loadOffer(value);
            case CREATE_OFFER -> shopHandler.createOffer(value);
            case DELETE_OFFER -> shopHandler.deleteOffer();
            case INSERT_CURRENCY -> shopHandler.insertCurrency();
            case EXTRACT_CURRENCY -> shopHandler.extractCurrency();
            case TOGGLE_TRANSFER -> shopHandler.toggleTransfer();
            case CLICK_BUFFER -> shopHandler.handleBufferClick();
        }
    }

    public enum Action {
        CREATE_OFFER, DELETE_OFFER, LOAD_OFFER, INSERT_CURRENCY, EXTRACT_CURRENCY, TOGGLE_TRANSFER, CLICK_BUFFER
    }

}

package com.glisco.numismaticoverhaul.network;

import com.glisco.numismaticoverhaul.ModComponents;
import com.glisco.numismaticoverhaul.currency.CurrencyConverter;
import com.glisco.numismaticoverhaul.currency.CurrencyHelper;
import io.wispforest.owo.network.ServerAccess;

public record RequestPurseActionC2SPacket(Action action, long value) {

    public static void handle(RequestPurseActionC2SPacket message, ServerAccess access) {
        final var player = access.player();
        final long value = message.value();

        switch (message.action()) {
            case STORE_ALL ->
                    ModComponents.CURRENCY.get(player).modify(CurrencyHelper.getMoneyInInventory(player, true));
            case EXTRACT -> {
                //Check if we can actually extract this much money to prevent cheeky packet forgery
                if (ModComponents.CURRENCY.get(player).getValue() < value) return;

                CurrencyConverter.getAsItemStackList(value).forEach(stack -> player.getInventory().offerOrDrop(stack));
                ModComponents.CURRENCY.get(player).modify(-value);
            }
            case EXTRACT_ALL -> {
                CurrencyConverter.getAsValidStacks(ModComponents.CURRENCY.get(player).getValue())
                        .forEach(stack -> player.getInventory().offerOrDrop(stack));

                ModComponents.CURRENCY.get(player).modify(-ModComponents.CURRENCY.get(player).getValue());
            }
        }
    }

    public static RequestPurseActionC2SPacket storeAll() {
        return new RequestPurseActionC2SPacket(Action.STORE_ALL, 0);
    }

    public static RequestPurseActionC2SPacket extractAll() {
        return new RequestPurseActionC2SPacket(Action.EXTRACT_ALL, 0);
    }

    public static RequestPurseActionC2SPacket extract(long amount) {
        return new RequestPurseActionC2SPacket(Action.EXTRACT, amount);
    }

    public enum Action {
        STORE_ALL, EXTRACT, EXTRACT_ALL
    }
}

